def hook(ctx, nb):
    if ctx.action.value_normalized == 'buy now':
        messages = []
        if ctx.predicates.product_price_over_budget:
            messages.append('The product price exceeds the budget. Please go back to search and find a cheaper product.')
        if ctx.predicates.required_options_unselected:
            messages.append('You haven\'t selected all required options (e.g., color, size, material). Please select the correct options before buying.')
        if messages:
            return {'kind': 'block_and_prompt', 'message': ' '.join(messages)}
    return None
